  function applyWardrobe(){for(const node of document.querySelectorAll('#pip .pip-sprite,#hubPip .pip-atlas-frame,#shopPip .pip-atlas-frame'))node.style.backgroundImage=wardrobe.art?'url("'+wardrobe.art+'")':'';}
