  const practiceTools=document.createElement('div');practiceTools.className='practice-tools';practiceTools.innerHTML='<p>Shared-device practice · ☆☆☆<br>Stars record independent practice on 1, 3 and 6 different days for each word. They are not money or an individual mastery score. Open words to review freely.</p><button id="practiceExport" type="button">Export practice</button><button id="practiceReset" type="button">Reset practice only</button>';els.dictionaryList.before(practiceTools);
