  async function returnPipToAnchor() { const epoch=runEpoch; const end = getPipPosition(state.anchor); const start = { left: els.pip.offsetLeft, top: els.pip.offsetTop }; const dx = end.left - start.left; const dy = end.top - start.top;if(Math.abs(dx)>1)els.pip.classList.toggle('face-left',dx<0); const motion = els.pip.animate([{ transform: "translate3d(0,0,0) scale(1)", opacity: 1 }, { transform: `translate3d(${dx * .52}px,${dy * .52 - els.game.clientHeight * .08}px,0) scale(.92)`, opacity: .78, offset: .52 }, { transform: `translate3d(${dx}px,${dy}px,0) scale(1)`, opacity: 1 }], { duration: 520, fill: "forwards", easing: "cubic-bezier(.16,1,.3,1)" }); await motion.finished.catch(()=>{});if(epoch!==runEpoch)return; els.pip.style.left = `${end.left}px`; els.pip.style.top = `${end.top}px`; motion.cancel(); els.pip.classList.add("flash"); burstAt(state.anchor); await sleep(260); els.pip.classList.remove("flash"); }

  async function completeCheckpoint() { const epoch=runEpoch;updateBeacon(true);state.busy = true; state.coins += 5; PipSupplies.earn(5); store.write("coins",state.coins); state.checkpoints += 1; store.write("checkpoints", state.checkpoints); sound.checkpoint(); updateHomeRecord(); PipAdventure.record(state.phase,state.score-state.stageStart,true); if (state.phase >= 5) { state.running = false; await announceBanner("SUMMIT CLEAR", "The islands are safe!", "Every beacon shines. You brought everyone home.", 2500); if(epoch===runEpoch)showResult(true); return; } await PipAdventure.checkpointStop(); if(!state.running||epoch!==runEpoch)return; await PipAdventure.chooseNext(state.phase); if(!state.running||epoch!==runEpoch)return; const nextPhase = state.phase + 1; state.stageStart=state.score; state.unlockedPhase = Math.max(state.unlockedPhase, nextPhase); state.selectedPhase = nextPhase; store.write("unlockedPhase", state.unlockedPhase); store.write("selectedPhase", nextPhase); state.phase = nextPhase; state.phaseScore = 0;updateBeacon(); state.bossMode = false; state.previousKind = ""; state.anchor.classList.remove("checkpoint"); els.game.classList.remove("at-checkpoint"); els.choices.innerHTML = ""; resetAnchor(); const pos=getPipPosition(state.anchor); els.pip.style.left=pos.left+"px"; els.pip.style.top=pos.top+"px"; applyPhase(nextPhase); els.promptVerb.textContent = "Ready for"; els.targetWord.textContent = `Phase ${nextPhase}`; els.promptHelp.textContent = phaseDetails().message; buildTrail(); updatePhasePicker(); updateHud(); await announceBanner(`PHASE ${nextPhase} UNLOCKED`, phaseDetails().name, `The beacon shines! On to ${phaseDetails().name}.`, 2500); pipSay(`Welcome to ${phaseDetails().name}.`, 2100); await sleep(320);if(epoch!==runEpoch)return; newRound(); }
